package com.example.kyrgyzkeyboard.ui.settings

import androidx.lifecycle.ViewModel
import dagger.hilt.android.lifecycle.HiltViewModel
import javax.inject.Inject
import androidx.lifecycle.viewModelScope
import com.example.kyrgyzkeyboard.data.model.KeyboardSettings
import com.example.kyrgyzkeyboard.data.repository.SettingsRepository
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.onEach
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch

/**
 * 设置页 ViewModel。
 *
 * DataStore（[preferences]）是权威源；同时把变更同步写入 [settingsRepo]
 * （基于 SharedPreferences），供 IME Service 侧同步消费，避免双写不一致。
 * ViewModel 只做状态搬运和分发，不含业务规则。
 */
@HiltViewModel
class SettingsViewModel @Inject constructor(
    private val preferences: SettingsPreferences,
    private val settingsRepo: SettingsRepository
) : ViewModel() {

    /** UI 状态流：始终反映当前 DataStore 中的设置。 */
    val settings: StateFlow<KeyboardSettings> = preferences.flow
        .onEach { snapshot -> mirror(snapshot) }
        .stateIn(
            scope = viewModelScope,
            started = SharingStarted.WhileSubscribed(5_000),
            initialValue = KeyboardSettings()
        )

    /**
     * 通用更新入口。key 使用 [SettingsPreferences] 定义的 PREF_* 常量。
     * value 类型不匹配时忽略（保持 ViewModel 纯粹）。
     */
    fun updateSetting(key: String, value: Any) {
        viewModelScope.launch {
            when (key) {
                SettingsPreferences.PREF_VIBRATE -> (value as? Boolean)?.let {
                    preferences.setVibrate(it)
                }
                SettingsPreferences.PREF_SOUND -> (value as? Boolean)?.let {
                    preferences.setSound(it)
                }
                SettingsPreferences.PREF_THEME -> (value as? String)?.let {
                    preferences.setTheme(it)
                }
                SettingsPreferences.PREF_FONT_SIZE -> (value as? Number)?.let {
                    preferences.setFontSize(it.toFloat())
                }
                SettingsPreferences.PREF_AUTO_CORRECTION -> (value as? Boolean)?.let {
                    preferences.setAutoCorrection(it)
                }
                SettingsPreferences.PREF_SWIPE_GESTURE -> (value as? Boolean)?.let {
                    preferences.setSwipeGesture(it)
                }
                SettingsPreferences.PREF_KYRGYZ_ASSOCIATION -> (value as? Boolean)?.let {
                    preferences.setKyrgyzAssociation(it)
                }
            }
        }
    }

    private suspend fun mirror(snapshot: KeyboardSettings) {
        settingsRepo.saveSettings(snapshot)
    }
}